static s16 searchKanjiCode(u16 code)
{
	u32 codeBytes[2];
	codeBytes[0] = u16(code >> 8) & 0xFF;
	codeBytes[1] = code & 0xFF;

	s16 len = strlen(kanji_convert_table) >> 1;
	s16 res = -1;

	for (s16 i = 0; i < len; i++) {
		if (kanji_convert_table[2 * i] == codeBytes[0] && kanji_convert_table[2 * i + 1] == codeBytes[1]) {
			res = i;
			break;
		}
	}

	return res;
}

