void System::updateSysClock()
{
	OSTick tick = OSGetTick();
	mEngineFrames++;
	mFrameTicks = tick - mPrevTick;
	mDeltaTime  = mFrameTicks / (f64)OS_TIMER_CLOCK;
	mTotalFrames++;
	if (mDeltaTime > f32(1.0f / 30.0f)) {
		mDeltaTime = f32(1.0f / 30.0f);
	}
	if (mDeltaTime < 0.0f) {
		mDeltaTime = 0.0f;
	}

	int time = tick - mFpsSampleStart;
	if (time > OS_TIMER_CLOCK) {
		mFPS                 = (f64)(OS_TIMER_CLOCK * (mEngineFrames - mFramesAtSampleStart)) / time;
		mFpsSampleStart      = tick;
		mFramesAtSampleStart = mEngineFrames;
	}
	mPrevTick = tick;
}

void PVWPolygonColourInfo::animate(f32* data, Colour& col)
{
	// If there is no animation loaded, don't do anything
	if (mTotalFrameCount == 0) {
		return;
	}

	if (data) {
		mCurrentFrame = std::fmodf(data[0], mTotalFrameCount);
	} else {
		// If no new data is provided, increment the current frame
		mCurrentFrame += gsys->getFrameTime() * (30.0f * mSpeed);

		// Wrap around if we've reached the end of the animation
		if (mCurrentFrame >= mTotalFrameCount - 1) {
			mCurrentFrame = 0.0f;
		}
	}

	// Animate colour and transparency separately
	mColourInfo.extract(mCurrentFrame, col);
	mAlphaInfo.extract(mCurrentFrame, col);
}

void P2DPrint::doCtrlCode(int inputChar)
{
	switch (inputChar) {
	case '\b': // backspace
	{
		mCursorX -= mCurrCharWidth;
		mCurrCharWidth = 0.0f;
		break;
	}
	case '\t': // horizontal tab
	{
		int width = mCharTabWidth;
		if (width > 0) {
			f32 oldX       = mCursorX;
			mCursorX       = f32(width + width * ((int)mCursorX / width));
			mCurrCharWidth = mCursorX - oldX;
		}
		break;
	}
	case '\n': // line feed
	{
		mCurrCharWidth = 0.0f;
		mCursorX       = mInitX;
		mCursorY       = mCursorY + mCharLeading;
		break;
	}
	case '\r': // carriage return
	{
		mCurrCharWidth = 0.0f;
		mCursorX       = mInitX;
		break;
	}
	case '\x1C': // file separator
	{
		mCursorX += 1.0f;
		break;
	}
	case '\x1D': // group separator
	{
		mCursorX -= 1.0f;
		break;
	}
	case '\x1E': // record separator
	{
		mCursorY -= 1.0f;
		break;
	}
	case '\x1F': // unit separator
	{
		mCursorY += 1.0f;
		break;
	}
	}
}

void Light::setLightSpot(f32 angle, int spotMode)
{
	if (angle <= 0.0f || angle > 90.0f) {
		spotMode = SPOT_NoAttn;
	}

	f32 constTerm;
	f32 linearTerm;
	f32 quadTerm;

	f32 angleRadians = angle * PI / 180.0f;
	f32 tmp;
	f32 cosTheta = cosf(angleRadians);

	switch (spotMode) {
	case SPOT_Linear:
	{
		constTerm  = -1000.0f * cosTheta;
		linearTerm = 1000.0f;
		quadTerm   = 0.0f;
		break;
	}
	case SPOT_Smooth:
	{
		constTerm  = -cosTheta / (1.0f - cosTheta);
		linearTerm = 1.0f / (1.0f - cosTheta);
		quadTerm   = 0.0f;
		break;
	}
	case SPOT_Quadratic:
	{
		constTerm  = 0.0f;
		linearTerm = -cosTheta / (1.0f - cosTheta);
		quadTerm   = 1.0f / ((1.0f - cosTheta));
		break;
	}
	case SPOT_Cubic:
	{
		tmp        = SQUARE((1.0f - cosTheta));
		constTerm  = (cosTheta * (cosTheta - 2.0f)) / tmp;
		linearTerm = 2.0f / tmp;
		quadTerm   = -1.0f / tmp;
		break;
	}
	case SPOT_Quartic:
	{
		tmp        = SQUARE((1.0f - cosTheta));
		constTerm  = -4.0f * cosTheta / tmp;
		linearTerm = 4.0f * (1.0f + cosTheta) / tmp;
		quadTerm   = -4.0f / tmp;
		break;
	}
	case SPOT_Special:
	{
		tmp        = SQUARE((1.0f - cosTheta));
		constTerm  = 1.0f - (2.0f * cosTheta * cosTheta) / tmp;
		linearTerm = 4.0f * cosTheta / tmp;
		quadTerm   = -2.0f / tmp;
		break;
	}
	case SPOT_NoAttn:
	default:
	{
		constTerm  = 1.0f;
		linearTerm = 0.0f;
		quadTerm   = 0.0f;
		break;
	}
	}

	mSpotConstTerm  = constTerm;
	mSpotLinearTerm = linearTerm;
	mSpotQuadTerm   = quadTerm;
	mLightValuesSet = 1;
}

