void Matrix4f::multiply(immut Matrix4f& other)
{
	Matrix4f result;

	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			result.mMtx[i][j] = 0.0f;
			for (int k = 0; k < 4; k++) {
				result.mMtx[i][j] += mMtx[i][k] * other.mMtx[k][j];
			}
		}
	}

	*this = result;
}

